 "content": "def transform(grid):
    """Project each colored cross along its row and column.

    An empty center surrounded on all four sides by gray cells marks a row
    and column that must remain uncolored. Original nonzero cells are retained;
    vertical projections take precedence at blank intersections.
    """
    h, w = len(grid), len(grid[0])
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    blocked_rows = set()
    blocked_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 3 and grid[r+1][c] == 3
                    and grid[r][c-1] == 3 and grid[r][c+1] == 3):
                blocked_rows.add(r)
                blocked_cols.add(c)

    out = [row[:] for row in grid]
    # Horizontal rays fill all empty cells along each colored-center row.
    for r, c, color in centers:
        for x in range(w):
            if grid[r][x] == 0:
                out[r][x] = color
    # Vertical rays overwrite horizontal color where lines cross.
    for r, c, color in centers:
        for y in range(h):
            if grid[y][c] == 0:
                out[y][c] = color

    # The hollow gray cross is a global mask; its row/column remain empty
    # except for original gray cells (which were preserved above).
    for r in blocked_rows:
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = 0
    for c in blocked_cols:
        for r in range(h):
            if grid[r][c] == 0:
                out[r][c] = 0
    return out


def _grid(h, w, cells):
    g = [[0] * w for _ in range(h)]
    for r, c, v in cells:
        g[r][c] = v
    return g


