                out[r][x]=color
    # Vertical rays span the grid; horizontal lines have priority at their
    # intersections whenever an original cross marker blocks the vertical ray.
    for r,c,color in centers:
        for y in range(h):
            if grid[y][c]==0:
                out[y][c]=color
    # Restore original colored centers (gray cells have always been preserved).
    for r,c,color in centers:
        out[r][c]=color
    return out

'''
