 "content": "def transform(grid):
    """Extend colored cross centers along their row and column axes."""
    h, w = len(grid), len(grid[0])
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    out = [row[:] for row in grid]
    for r, c, color in centers:
        for x in range(w):
            if grid[r][x] == 0:
                out[r][x] = color
    for r, c, color in centers:
        for y in range(h):
            if grid[y][c] == 0:
                out[y][c] = color
    # On a row containing several colored crosses, extend the outermost
    # center's own color outward past its immediate gray side arm.
    for r in range(h):
        row_centers = [(c, color) for rr, c, color in centers if rr == r]
        if len(row_centers) < 2:
            continue
        lo = min(c for c, _ in row_centers)
        hi = max(c for c, _ in row_centers)
        for c, color in row_centers:
            for dc in (-1, 1):
                if (dc < 0 and c != lo) or (dc > 0 and c != hi):
                    continue
                x = c + dc
                if 0 <= x < w and grid[r][x] == 3:
                    x += dc
                while 0 <= x < w and grid[r][x] == 0:
                    out[r][x] = color
                    x += dc
    return out


def _make(h, w, cells):
    g = [[0] * w for _ in range(h)]
    for r, c, v in cells:
        g[r][c] = v
    return g


