    A ray stops at another original colored or gray cell. Hollow gray crosses
    reserve their center row/column, leaving a gap there while rays continue.
    Horizontal fills are followed by vertical fills, which win at crossings.
    """
    h, w = len(grid), len(grid[0])
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    hollow = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r - 1][c] == 3
                    and grid[r + 1][c] == 3 and grid[r][c - 1] == 3
                    and grid[r][c + 1] == 3):
                hollow.append((r, c))
    hollow_rows = {r for r, c in hollow}
    hollow_cols = {c for r, c in hollow}
    out = [row[:] for row in grid]

    # Paint horizontal rays. The immediate adjacent gray arm belongs to the
    # source cross and is passed; subsequent nonzero cells stop the ray.
    for r, c, color in centers:
        for dc in (-1, 1):
            x = c + dc
            if 0 <= x < w and grid[r][x] == 3:
                x += dc
            while 0 <= x < w:
                if grid[r][x] != 0:
                    break
                if x not in hollow_cols:
                    out[r][x] = color
                x += dc

    # Paint vertical rays afterward for intersection priority.
    for r, c, color in centers:
        for dr in (-1, 1):
            y = r + dr
            if 0 <= y < h and grid[y][c] == 3:
                y += dr
            while 0 <= y < h:
                if grid[y][c] != 0:
                    break
                if y not in hollow_rows:
                    out[y][c] = color
                y += dr
