    A ray passes its source cross's immediate gray arm, then stops at the
    next original nonzero marker. Gray-only hollow crosses leave a gap at
    their column in horizontal projections. Vertical rays take priority at
    intersections.
    """
    h, w = len(grid), len(grid[0])
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    hollow_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 3 and grid[r+1][c] == 3
                    and grid[r][c-1] == 3 and grid[r][c+1] == 3):
                hollow_cols.add(c)

    out = [row[:] for row in grid]
    # Horizontal rays.
    for r, c, color in centers:
        for dc in (-1, 1):
            x = c + dc
            while 0 <= x < w:
                value = grid[r][x]
                if value != 0:
                    if value == 3 and abs(x - c) == 1:
                        x += dc
                        continue
                    break
                if x not in hollow_cols:
                    out[r][x] = color
                x += dc
    # Vertical rays, later so they win at blank intersections.
    for r, c, color in centers:
        for dr in (-1, 1):
            y = r + dr
            while 0 <= y < h:
                value = grid[y][c]
                if value != 0:
                    if value == 3 and abs(y - r) == 1:
                        y += dr
                        continue
                    break
                out[y][c] = color
                y += dr
    return out


def _make(h, w, cells):
    g = [[0] * w for _ in range(h)]
    for r, c, v in cells:
        g[r][c] = v
    return g


def _test_input():
    return _make(19, 19, [
        (2,6,3),(3,5,3),(3,6,8),(3,7,3),(4,6,3),
        (3,13,3),(4,12,3),(4,13,4),(4,14,3),(5,13,3),
