 "content": "def transform(grid):
    """Extend each colored cross along its row and column rays.

    The source cross's own gray arms are traversable. Other numbered centers
    block rays. At line intersections the nearest source determines the color;
    ties favor the vertical projection. Gray arms remain unchanged.
    """
    h, w = len(grid), len(grid[0])
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    out = [row[:] for row in grid]

    def distance_from(r, c, dr, dc, target_r, target_c):
        rr, cc = r + dr, c + dc
        dist = 1
        while 0 <= rr < h and 0 <= cc < w:
            if (rr, cc) == (target_r, target_c):
                return dist
            # The source's first gray arm may be crossed; any other numbered
            # center ends this ray.
            if grid[rr][cc] not in (0, 3):
                return None
            rr += dr
            cc += dc
            dist += 1
        return None

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            candidates = []  # (distance, orientation, color)
            for sr, sc, color in centers:
                if sr == r:
                    # To reach this cell, the row segment must not encounter
                    # another colored center. Gray arms are transparent.
                    step = 1 if c > sc else -1
                    x = sc + step
                    while min(sc, c) < x < max(sc, c):
                        if grid[r][x] not in (0, 3):
                            break
                        x += step
                    else:
                        candidates.append((abs(c - sc), 1, color))
                if sc == c:
                    step = 1 if r > sr else -1
                    y = sr + step
                    while min(sr, r) < y < max(sr, r):
                        if grid[y][c] not in (0, 3):
                            break
                        y += step
                    else:
                        candidates.append((abs(r - sr), 0, color))
            if candidates:
                out[r][c] = min(candidates)[2]
    return out


def _make(h, w, cells):
    g = [[0] * w for _ in range(h)]
    for r, c, color in cells:
        g[r][c] = color
    return g


def _test_input():
    return _make(19, 19, [
        (2,6,3),(3,5,3),(3,6,8),(3,7,3),(4,6,3),
        (3,13,3),(4,12,3),(4,13,4),(4,14,3),(5,13,3),
        (9,8,3),(10,7,3),(10,9,3),(11,8,3),
        (11,14,3),(12,13,3),(12,14,1),(12,15,3),(13,14,3),
        (13,3,3),(14,2,3),(14,3,2),(14,4,3),(15,3,3)])


if __name__ == '__main__':
    result = transform(_test_input())
    assert len(result) == 19 and all(len(row) == 19 for row in result)
