    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    out = [row[:] for row in grid]

    def distance_from(r, c, dr, dc, target_r, target_c):
        rr, cc = r + dr, c + dc
        dist = 1
        while 0 <= rr < h and 0 <= cc < w:
            if (rr, cc) == (target_r, target_c):
                return dist
            # The source's first gray arm may be crossed; any other numbered
            # center ends this ray.
            if grid[rr][cc] not in (0, 3):
